export function science(u){
u('biology',7,1,'細胞與顯微鏡','細胞是生物構造與功能的基本單位。細胞膜調節物質進出；細胞核包含主要遺傳物質。光學顯微鏡總倍率＝目鏡倍率×物鏡倍率。','10 倍目鏡配 40 倍物鏡，總倍率 400 倍。由低倍換高倍，視野範圍變小、可見細胞數通常減少。','植物細胞不一定有葉綠體，例如多數根部細胞；動物細胞沒有細胞壁。','畫一個植物細胞，標出細胞膜、細胞壁、細胞核，說明各自功能。',[
['目鏡 10 倍、物鏡 20 倍，總倍率為？',['30','200','2','1000'],1,'顯微鏡總倍率相乘：10×20＝200 倍。'],
['由低倍鏡換成高倍鏡，一般何者正確？',['視野變大','看到細胞數增加','細胞影像變大，視野範圍縮小','完全不必再調焦'],2,'倍率增加放大局部，所以影像變大、涵蓋範圍變小。']]);
u('biology',7,1,'養分、光合作用與呼吸作用','光合作用利用光能將二氧化碳與水轉為有機養分並釋出氧。呼吸作用分解養分，釋放可供細胞使用的能量；植物也會呼吸。','白天綠色植物可能同時進行光合作用與呼吸作用。夜間無光時光合作用停止，但仍持續呼吸。','植物不是只有晚上才呼吸；肥料供應礦物質，不是植物有機養分的唯一來源。','設計比較光照有無的實驗，說明需要控制水量、植物種類等條件。',[
['綠色植物晚上仍持續進行的是？',['只有光合作用','呼吸作用','完全沒有代謝','不再消耗養分'],1,'活細胞需要能量，呼吸作用日夜持續。'],
['研究光照對植物生長的影響，應主要改變什麼？',['植物品種與水量','只有光照條件','所有條件','花盆顏色與土壤'],1,'光照是操縱變因，其他可能影響生長的條件盡量控制一致。']]);
u('biology',7,1,'運輸、消化與恆定','人體消化把大分子養分分解為可吸收的小分子，小腸是主要吸收場所。循環系統運輸物質；恆定透過調節維持內部環境相對穩定。','運動時肌肉需要更多氧與養分，心跳與呼吸會加快；流汗與皮膚血流變化協助散熱。','動脈是離開心臟的血管，不必然運送充氧血；肺動脈是重要例外。','用箭頭畫出血液經心臟、肺與全身的大致路徑。',[
['人體吸收大部分消化後養分的器官是？',['食道','胃','小腸','氣管'],2,'小腸具有摺皺與絨毛，增加吸收面積。'],
['「動脈」的判定依據是？',['血一定鮮紅','血液離開心臟','血含氧一定較多','血管都很淺'],1,'動靜脈依相對心臟的血流方向命名，與含氧高低不是同一分類。']]);
u('biology',7,2,'神經、內分泌與反應','神經系統透過訊息傳遞快速協調；內分泌腺將激素送入血液，作用通常較持久。反射能以較短路徑做出快速反應。','碰到燙物時可先縮手再清楚感到疼痛；部分反射經脊髓整合，但訊息仍可上傳大腦。','反射不代表完全沒有神經控制，也不代表大腦永遠不接收訊息。','比較聽到鈴聲轉頭與長期身高增加，使用不同的調節時間尺度。',[
['快速縮手反射的主要好處是？',['增加受傷時間','快速避開傷害','停止所有感覺','不需任何神經'],1,'反射使身體能迅速回應刺激，減少傷害。'],
['內分泌腺分泌的激素主要藉什麼送達作用部位？',['食道','汗液','血液','空氣'],2,'激素由內分泌腺進入血液，再到特定標的細胞作用。']]);
u('biology',7,2,'生殖、遺傳與演化','有性生殖結合配子的遺傳資訊；無性生殖通常保留親代相近的遺傳組合。自然選擇作用於既存差異，族群特徵可隨世代改變。','若 A 為顯性、a 為隱性，Aa×Aa 的子代可能為 AA、Aa、aa，簡單單基因模型下比例 1:2:1。','顯性不代表更優秀、更常見或一定被遺傳；演化不是個體想改變就能改變。','用四格表列出 Aa×Aa 的配子組合，解釋基因型與表現型差異。',[
['單基因完全顯性模型 Aa×Aa，子代為 aa 的機率？',['0','1/4','1/2','3/4'],1,'四格為 AA、Aa、Aa、aa，aa 占 1/4。'],
['抗藥性細菌比例增加，最合理的解釋是？',['細菌有意志地變強','藥物選擇下較能存活的變異留下較多後代','每隻細菌都立刻變同樣','抗藥性與繁殖無關'],1,'自然選擇使具有較適應環境特徵的個體留下較多後代。']]);
u('biology',7,2,'分類、生態系與能量流動','生物分類反映特徵與親緣關係。生態系包括生物與非生物因子；食物鏈箭頭由被吃者指向取食者，表示物質與能量傳遞。','草→蚱蜢→青蛙→蛇。生產者把光能轉為化學能，各營養階層消耗部分能量於生命活動。','能量流動與物質循環不同；能量不會無限完整循環回生產者。','畫校園食物網，加入分解者並說明移除某物種可能造成的連鎖影響。',[
['草→兔→狐的箭頭主要表示？',['生物大小','能量由食物傳向消費者','移動方向','演化先後'],1,'兔吃草、狐吃兔，能量沿食物關係傳遞。'],
['分解者在生態系的主要作用是？',['創造全部太陽能','分解遺體，協助物質回到環境','使物質永不循環','只能捕食大型動物'],1,'分解作用使養分回到環境，再被其他生物利用。']]);

u('physics',8,1,'測量、密度與實驗變因','測量需記錄數值與單位。密度＝質量÷體積，是相同條件下物質的性質之一。公平實驗改變操縱變因、測量應變變因、控制其他重要條件。','質量 54 g、體積 20 cm³，密度＝2.7 g/cm³。物體切半，質量與體積都減半，密度不變。','重不代表密度大，還要比較體積；重複測量可減少隨機誤差影響。','用等體積的兩種材料比較質量，解釋密度差異。',[
['質量 80 g、體積 10 cm³，密度為？',['0.125','8','70','800'],1,'80÷10＝8 g/cm³。'],
['同材質實心金屬切成兩半，各半的密度會？',['變一半','變兩倍','保持相同','變零'],2,'同條件下質量與體積同比縮小，比值密度不變。']]);
u('physics',8,1,'聲音與波動','聲音是介質中的振動傳遞。頻率影響音調，振幅與響度有關；聲速受介質及溫度等條件影響。回聲距離需計算來回路徑。','聽到回聲的間隔為 2 秒，聲速取 340 m/s，障礙物距離＝340×2÷2＝340 m。','聲音不能在真空中傳遞；越大聲不代表頻率越高。','用橡皮筋比較張力不同的音調，說明控制哪些條件。',[
['頻率增加，主要改變聲音哪項性質？',['音調變高','聲速必變快','音量必變大','不能傳播'],0,'音調主要由振動頻率決定，頻率越高音調越高。'],
['回聲 0.5 秒後傳回，聲速 340 m/s，牆距離約？',['85 m','170 m','340 m','680 m'],0,'0.5 秒是來回時間，單程距離 340×0.5÷2＝85 m。']]);
u('physics',8,1,'光的反射、折射與成像','反射角等於入射角，角度皆由法線量起。光跨介質時可能折射；凸透鏡可因物距不同形成不同的像。','入射光與鏡面夾 30°，與法線夾 60°，所以反射角為 60°。','把鏡面當角度基準會算錯；凸透鏡不一定只會形成放大的像。','以紙筆畫平面鏡、法線與光線，標出入射角與反射角。',[
['入射角 35°，平面鏡反射角是多少？',['17.5°','35°','55°','70°'],1,'反射定律：反射角等於入射角。'],
['光線與鏡面夾 20°，入射角為？',['20°','40°','70°','90°'],2,'入射角從法線量起，90−20＝70°。']]);
u('physics',8,2,'溫度、熱量與熱傳播','溫度描述冷熱狀態，熱量是在溫差下傳遞的能量。熱可藉傳導、對流和輻射傳播。在沒有相變且比熱近似固定時，Q＝mcΔT。','同質量的水與金屬接受相同熱量，比熱較小者溫度變化較大。太陽能量可藉輻射穿過真空。','溫度較高不代表總內能一定較多；熱量與溫度不是同一單位。','比較金屬湯匙與木湯匙置於溫水後的感受，解釋熱傳導差異。',[
['太陽熱能主要以何種方式傳至地球？',['傳導','對流','輻射','水流'],2,'輻射不需要物質介質，可穿越太空。'],
['同物質、同溫升，質量加倍所需熱量如何？',['減半','不變','加倍','變四倍'],2,'Q＝mcΔT，在 c 和 ΔT 相同時與質量成正比。']]);
u('physics',9,1,'運動、力與牛頓定律','平均速率＝總路程÷總時間；速度還包含方向。合力造成速度的改變，合力為零時可靜止或等速度運動。F＝ma 用一致單位計算。','質量 2 kg，合力 6 N，則加速度 3 m/s²。等速度前進不需要持續增加合力。','作用力與反作用力作用在不同物體上，不能當成同一物體的平衡力。','畫出平放桌上的書所受重力與支持力，說明兩力的施力者。',[
['2 kg 物體受合力 10 N，加速度為？',['2 m/s²','5 m/s²','10 m/s²','20 m/s²'],1,'a＝F/m＝10/2＝5 m/s²。'],
['物體合力為零，可能的運動狀態是？',['只能靜止','一定加速','靜止或等速度直線運動','必定圓周運動'],2,'牛頓第一定律：合力為零時維持原速度。']]);
u('physics',9,1,'功、能量與簡單機械','力在位移方向的分量做功，方向相同時 W＝Fs。理想機械可省力但通常增加移動距離，不能憑空省功。能量可以轉換，總量遵守守恆。','槓桿平衡：施力×施力臂＝抗力×抗力臂。力臂是支點到力作用線的垂直距離。','力臂不是任意量到施力點的長度；靜止提著物品時物品沒有位移，不對它做機械功。','用互動槓桿調整力與距離，找出三組平衡組合。',[
['沿位移方向施力 8 N，移動 3 m，做功？',['5 J','11 J','24 J','64 J'],2,'W＝F×s＝8×3＝24 J。'],
['左側 20 N、力臂 30 cm；右側力臂 60 cm，平衡需多少力？',['5 N','10 N','20 N','40 N'],1,'20×30＝F×60，所以 F＝10 N。']]);
u('physics',9,2,'電路、電功率與磁作用','電流需要閉合導電路徑。歐姆定律 V＝IR 適用於符合條件的電阻元件。串聯電流相同，並聯各支路兩端電壓相同。功率 P＝VI。','6 V 電池接 3 Ω 電阻，電流 2 A，功率 12 W。實際電路應避免短路。','電流不是流過電阻就被消耗掉；消耗或轉換的是電能。','在虛擬電路中固定電壓，預測電阻加倍後電流如何變化。',[
['電壓 12 V、電阻 4 Ω，電流為？',['0.33 A','3 A','8 A','48 A'],1,'I＝V/R＝12/4＝3 A。'],
['兩電阻並聯在同一電池上，何者相同？',['各支路電流必相同','各支路電壓','兩電阻值','各支路功率必相同'],1,'並聯各支路接在相同兩端點，因此電位差相同。']]);

u('chemistry',8,1,'物質分類與粒子模型','純物質包括元素與化合物，成分固定；混合物比例可以改變。原子可組成分子，化學變化涉及原子的重新排列。','氧氣 O₂ 是元素形成的分子；水 H₂O 是化合物；空氣是多種氣體的混合物。','分子不一定是化合物，例如 O₂；化合物不是用過濾就能分成元素。','分類食鹽水、鐵片、純水與空氣，逐一說明理由。',[
['何者為混合物？',['純水','氧氣','空氣','純鐵'],2,'空氣含氮、氧等多種物質，比例可隨環境變動。'],
['O₂ 應分類為？',['化合物','元素','混合物','離子溶液'],1,'只有氧一種元素，即使是雙原子分子仍屬元素。']]);
u('chemistry',8,1,'原子結構與週期表','原子核含質子與中子，電子在核外。原子序＝質子數，中性原子的電子數等於質子數。同位素質子數相同、中子數不同。','碳-12 與碳-14 都有 6 個質子，分別有 6 和 8 個中子。失去電子形成正離子。','帶正電通常是失去電子，不是多出質子；改變質子數會改變元素種類。','以原子序 11 的鈉為例，說明中性原子與鈉離子的電子數差異。',[
['同位素必定具有相同的？',['中子數','質量數','質子數','總粒子數'],2,'同元素的質子數相同，但中子數可不同。'],
['中性原子失去一個電子後通常形成？',['負一價離子','正一價離子','新元素','中子'],1,'電子帶負電，少一個電子使總電荷為 +1。']]);
u('chemistry',8,2,'反應式與質量守恆','化學反應中原子種類及各種原子總數守恆。平衡反應式調整係數，不改化學式下標。密閉系統反應前後總質量相同。','2H₂＋O₂→2H₂O，左右氫原子皆 4 個、氧原子皆 2 個。','開放容器產生氣體逸出會使秤得質量減少，但不代表物質憑空消失。','畫粒子圖表示氫氧生成水，核對每種原子數。',[
['平衡 H₂＋O₂→H₂O 的係數依序為？',['1,1,1','2,1,2','1,2,1','2,2,1'],1,'2H₂＋O₂→2H₂O，使左右氫 4、氧 2。'],
['密閉容器反應前總質量 120 g，反應後應為？',['一定變小','120 g','一定變大','0 g'],1,'沒有物質進出時，化學反應遵守質量守恆。']]);
u('chemistry',8,2,'溶液、濃度與溶解度','質量百分濃度＝溶質質量÷溶液質量×100%。溶液質量是溶質加溶劑。溶解度描述指定溫度下的溶解上限。','10 g 食鹽加 90 g 水，溶液 100 g，濃度 10%。加水後溶質質量不變，但濃度下降。','濃度分母不是只有水的質量；攪拌加快溶解，不必然提高平衡溶解度。','比較在兩杯等量水中加入不同鹽量的濃度，列清分子分母。',[
['20 g 糖溶於 80 g 水，質量百分濃度？',['20%','25%','80%','100%'],0,'溶液質量 20＋80＝100 g，20/100×100%＝20%。'],
['同一杯鹽水加入純水後，何者維持不變？',['濃度','溶液質量','食鹽質量','水的質量'],2,'沒有鹽離開，食鹽質量不變；水量與溶液量增加，濃度下降。']]);
u('chemistry',8,2,'酸鹼、鹽類與中和','在一般國中水溶液情境，pH 小於 7 呈酸性、大於 7 呈鹼性。酸鹼指示劑顏色反映酸鹼性。中和涉及酸鹼反應，最終性質仍與用量等條件有關。','酸性水溶液使藍色石蕊變紅，鹼性水溶液使紅色石蕊變藍。不能用味覺檢測未知藥品。','酸和鹼混合不保證剛好中性；若酸過量可能仍呈酸性。','使用提供的安全模擬資料，比較 pH 與指示劑顏色，不自行混合清潔劑。',[
['pH＝3 的一般水溶液呈？',['酸性','中性','鹼性','一定無色'],0,'pH 小於 7，屬酸性；顏色不能由 pH 直接推定。'],
['酸與鹼混合後一定為中性嗎？',['一定','不一定，需考慮用量及性質','一定是酸','一定是鹼'],1,'若酸或鹼有過量，混合後可能仍偏酸或偏鹼。']]);
u('chemistry',9,2,'氧化還原、有機物與材料','國中可先用與氧結合、失去氧理解部分氧化還原。燃燒需要燃料、助燃物與適當溫度。有機材料的特性與用途相關，選材還需思考環境成本。','鐵在氧與水參與下容易生鏽；塗漆可隔離環境。塑膠分類與回收方式取決於材質。','不是所有含碳化合物都分類為有機物；如二氧化碳通常列為無機物。','比較可重複使用容器與一次性容器，記錄使用次數、清洗與回收條件。',[
['鐵表面塗漆主要如何防鏽？',['增加鐵的重量','隔離氧與水等環境因素','讓鐵變成塑膠','使鐵原子消失'],1,'塗層形成阻隔，減少鐵與促進鏽蝕的環境接觸。'],
['下列哪項最能評估材料是否較環保？',['只看顏色','只看是否印綠葉','考慮製造、使用與廢棄整體影響','越重一定越好'],2,'材料的環境影響須考慮生命週期，不能由外觀判斷。']]);

u('earth',9,1,'岩石、板塊與地震','岩石可依形成過程分為火成岩、沉積岩與變質岩。板塊互動造成多種地質活動；地震能量釋放位置為震源，地表正上方為震央。','岩漿冷卻凝固形成火成岩；岩層受高溫高壓但未熔融可形成變質岩。','變質不是一定先熔化；震度描述各地搖晃程度，與地震規模概念不同。','用兩張紙表示板塊聚合、張裂、錯動，說明相對運動。',[
['岩漿冷卻凝固主要形成？',['火成岩','沉積岩','任何岩都一樣','土壤'],0,'火成岩由岩漿或熔岩冷卻凝固形成。'],
['震央是指？',['地心','震源正上方的地表位置','每個搖最久的地點','所有斷層交點'],1,'震源在地下，震央是其垂直投影到地表的位置。']]);
u('earth',9,1,'水循環、海洋與地形','太陽能與重力驅動水循環；蒸發、凝結、降水、地表逕流和地下水彼此連結。流水與海浪可造成侵蝕、搬運和沉積。','河流出山口流速降低，沉積物堆積可形成沖積扇；海陸升溫不同形成局部環流。','地下水不是取之不盡；過量抽取可能導致地層下陷。','畫出一滴水由海洋到山區再回海洋的旅程，標記過程。',[
['河流流速減慢時，較容易發生？',['沉積','所有水立即蒸發','岩石熔化','板塊消失'],0,'流速下降使搬運能力減弱，顆粒較容易沉降。'],
['水循環中雲滴形成主要經過？',['熔化','凝結','燃燒','核反應'],1,'水蒸氣冷卻到適合條件，凝結成小水滴。']]);
u('earth',9,1,'天氣、鋒面與臺灣季風','天氣是短時間大氣狀態，氣候是長期統計特徵。空氣受熱上升、冷卻可能凝結成雲；季風與地形共同影響臺灣降雨分布。','冬季東北季風遇臺灣北部與東北部地形抬升，迎風區較容易降雨。','不能以某一天很冷就否定長期氣候變化；迎背風面依風向而變。','比較冬夏風向，推論同一山脈哪側較可能成為迎風面。',[
['描述「今天午後有雷陣雨」屬於？',['天氣','數十年氣候平均','地質年代','潮汐週期'],0,'今天的短期大氣狀態屬天氣。'],
['冬季東北季風時，臺灣哪類地區較容易出現地形雨？',['迎風的北部、東北部山區','所有西南平地一定暴雨','每個地點完全相同','只有離島'],0,'濕空氣在迎風坡抬升冷卻，較容易凝結降雨。']]);
u('earth',9,2,'地球運動、四季與月相','地球自轉造成晝夜交替，公轉加上地軸傾斜使各地日照角度和晝長隨季節變化。月相是所見月球受光面的改變。','北半球夏季，北半球偏向太陽，日照較直接且白晝較長。滿月時地球大致位於太陽與月球之間。','四季主要不是因地球離太陽遠近；月相也不是每月被地球影子遮住。','用燈與球模型觀察月相，分清日照面與觀察角度。',[
['四季形成的主要原因為？',['地球形狀每天改變','地軸傾斜與公轉','月球遮住太陽','每日自轉速度改變'],1,'地軸傾斜使公轉過程中兩半球的日照角度與晝長改變。'],
['平常月相變化主要是？',['月球自行發光變強弱','看到的受光面比例改變','每天發生月食','月球大小改變'],1,'月球反射太陽光，隨相對位置改變，地球上可見的受光面比例不同。']]);
u('earth',9,2,'太陽系、星空與尺度','太陽是恆星，行星主要反射恆星光。光年是光在一年走過的距離單位；天文尺度常用科學記號表示。觀測描述需記錄時間、方向與條件。','光年用來表示遙遠天體距離，不是天體年齡。地球由西向東自轉，使星空看似由東向西移動。','亮度不只與距離有關，也與天體本身發光能力等因素有關。','連續幾晚同一時間記錄一顆亮星方向，先確認天氣與觀察位置。',[
['光年是哪一種單位？',['時間','距離','亮度','速度'],1,'光年表示光在一年走過的距離。'],
['太陽屬於？',['行星','衛星','恆星','彗星'],2,'太陽是能自行發光的恆星。']]);
u('earth',9,2,'氣候變遷與永續探究','氣候研究須依長時間、多地點與多類資料。溫室效應是自然過程，人類增加溫室氣體可增強暖化。減緩與調適解決不同面向。','節能減排屬減緩；改善排水、準備熱浪避暑空間屬調適。單次天氣不能代表長期趨勢。','臭氧洞與全球暖化不是相同現象；不要把所有災害都歸因於單一因素。','提出校園節能方案，先量測基準用電，再比較改善前後。',[
['哪項最適合判斷氣候的長期趨勢？',['昨天體感','單一照片','數十年連續觀測資料','一天的網路留言'],2,'長期連續資料有助排除短期波動並辨識趨勢。'],
['降低建築能源消耗以減少排放，主要屬於？',['氣候減緩','月相觀測','板塊測量','把天氣取消'],0,'減緩是降低造成氣候變化的排放或增強吸收。']]);

u('biology',7,1,'物質進出細胞與酵素催化作用','細胞膜具有選擇通透性。小分子如氧氣、二氧化碳可藉擴散作用直接通過脂雙層；水可透過滲透作用進出細胞。酵素是生物體內的蛋白質催化劑，具專一性，活性受溫度與 pH 值顯著影響。','紅血球置於純水中會因水分大量滲透進入而膨脹破裂；置於高濃度濃食鹽水中則會滲透失水萎縮。唾液澱粉酶在人體 37°C 且接近中性環境下催化效率最高。','植物細胞置於純水不會破裂，因細胞壁提供機械支持抗膨壓；煮沸會使酵素蛋白質變性失去活性，降溫後無法恢復催化功能。','設計一個對照實驗，比較新鮮鳳梨汁（含蛋白質水解酶）與煮沸放涼的鳳梨汁對奶酪或果凍凝固的影響。',[
 ['將人類紅血球置入蒸餾水中，一段時間後最可能發生的現象是？',['細胞萎縮變小','細胞膨脹甚至破裂','細胞形狀完全不變','細胞生成細胞壁'],1,'蒸餾水濃度低於細胞質，水分子大量滲透進入紅血球內，因無細胞壁保護最終膨脹破裂。'],
 ['關於酵素特性的敘述，下列何者正確？',['同一種酵素可催化人體內所有化學反應','酵素的主要成分為無機鹽類','每種酵素通常只能催化特定受質反應','酵素在 100°C 沸水中催化活性最高'],2,'酵素具有專一性（鎖鑰模型），一種酵素通常只能結合特定受質進行催化反應。']]);
u('biology',7,1,'植物的體內運輸與水分恆定','維管束植物靠木質部與韌皮部進行運輸。木質部由下往上單向運送水分與礦物質，主要動力來自葉片氣孔的蒸散作用，輔以根壓與毛細現象；韌皮部負責運送葉片光合作用合成的蔗糖等有機養分，可雙向運送。','晴天中午陽光強烈時，蒸散作用旺盛，驅動水分從根毛快速上升至樹冠頂部；若空氣過度乾燥，保衛細胞失水萎縮導致氣孔關閉，可防止水分過度散失。','保衛細胞吸水膨脹時氣孔才會打開（內壁較厚外壁較薄）；木質部運輸不需要消耗細胞 ATP 能量，為物理拉力驅動。','取芹菜葉柄插入紅墨水中靜置半小時，橫切葉柄觀察紅色染料集中在何種組織，並說明其運輸方向。',[
 ['驅動高大喬木將水分從根部運送到數十公尺高樹葉的最主要動力是？',['根壓的向上推力','葉片的蒸散拉力','韌皮部的收縮搏動','土壤顆粒的排斥力'],1,'葉片水分蒸散產生的負壓拉力，透過水分子間的凝聚力形成連續水柱，是植物水分上升的主動力。'],
 ['關於植物體內養分運送的組織與方向，下列何者正確？',['木質部運送葡萄糖，僅向下運輸','韌皮部運送有機養分，可向上或向下運輸','木質部運送蛋白質，雙向流動','韌皮部運送無機鹽，只向上運輸'],1,'韌皮部篩管運送光合作用產物（以蔗糖為主），可依供需部位向上運至果實或向下運至根部儲存。']]);
u('biology',7,2,'動物呼吸系統與排泄泌尿作用','呼吸系統進行氣體交換：吸氣時肋骨上提、橫膈下降，胸腔體積擴大、壓力降低，外界空氣進入肺泡；排泄系統排除細胞代謝產生的含氮廢物。蛋白質代謝產生有毒的氨，人體肝臟先將其轉化為毒性較低的尿素，再由腎臟過濾形成尿液排出。','劇烈運動時血液中二氧化碳濃度升高，刺激腦幹呼吸中樞加快呼吸頻率以加速排除二氧化碳；腎臟腎絲球過濾血液，腎小管再將有用的葡萄糖與大部分水分重吸收回血液。','呼吸運動受血液中「二氧化碳濃度」主導調控，非缺氧為主；排泄（排尿）指排出代謝廢物，與排遺（排便，排出未消化食物殘渣）是不同生理途徑。','利用寶特瓶、氣球與吸管製作胸腔呼吸模型，拉動底部氣球薄膜說明橫膈升降與肺泡氣壓體積之關係。',[
 ['當人體吸氣時，胸腔各部位的變化與氣壓關係應為？',['肋骨下降、橫膈上升，胸腔氣壓大於外界','肋骨上提、橫膈下降，胸腔氣壓小於外界','肋骨與橫膈同時靜止，空氣自然灌入','橫膈上升、胸廓縮小，促使氣體進入肺部'],1,'吸氣為主動過程：外肋間肌收縮肋骨上提、橫膈收縮下降，胸廓擴大使胸內壓降低，空氣吸入。'],
 ['人體細胞代謝蛋白質所產生的含氮廢物，其主要的解毒與排泄途徑依序為？',['腎臟製造氨→膀胱排尿素','肝臟將氨轉為尿素→腎臟過濾排尿','胃直接分解氨→大腸排遺','肺臟將氨氧化為氣體呼出'],1,'蛋白質代謝產生高毒性的氨，經肝臟轉換為低毒性的尿素，最後隨血液流經腎臟過濾成尿液排出。']]);
u('biology',7,2,'細胞分裂、減數分裂與生殖','細胞分裂（有絲分裂）複製染色體一次、分裂一次，產生兩個染色體套數不變（2n→2n）的體細胞，用於生長與修補；減數分裂複製染色體一次、連續分裂兩次，同源染色體分離，產生四個染色體套數減半（2n→1n）的配子（精子或卵）。','人類體細胞具 23 對（46 條）染色體，經過減數分裂產生的精子或卵細胞各自具有 23 條單套染色體，受精結合後恢復為 46 條二套染色體，維持世代染色體數目恆定。','減數分裂中「同源染色體分離」發生在第一次分裂，「複製的姊妹染色分體分離」發生在第二次分裂；無性生殖通常不涉及減數分裂與受精作用。','用紙黏土製作代表一對同源染色體的模型，模擬減數分裂兩次分裂過程中染色體的排列與分離步驟。',[
 ['人體體細胞有 46 條染色體，若一細胞進行減數分裂，最後形成的精子中含有幾條染色體？',['46 條','92 條','23 條','23 對'],2,'減數分裂使配子染色體數減半，由雙套 46 條變為單套 23 條（非成對）。'],
 ['關於有絲分裂（細胞分裂）與減數分裂的比較，下列何者正確？',['有絲分裂分裂兩次，減數分裂分裂一次','減數分裂後子細胞染色體數目維持不變','有絲分裂產生 2 個子細胞，減數分裂產生 4 個子細胞','兩者皆會使子細胞的基因組合完全減半'],2,'有絲分裂分裂 1 次產生 2 個同套數子細胞；減數分裂連續分裂 2 次產生 4 個半套數配子。']]);
u('biology',7,2,'孟德爾遺傳法則與性別性聯遺傳','孟德爾提出分離律與自由配合律：成對遺傳因子在形成配子時彼此分離，不同對因子獨立分配。顯性等位基因會遮蔽隱性等位基因的表現。人類性別由第 23 對性染色體決定（女性 XX，男性 XY），紅綠色盲等性聯遺傳基因常位於 X 染色體上。','高莖豌豆（Tt）自交，子代基因型比例為 TT:Tt:tt＝1:2:1，表現型高莖:矮莖＝3:1。紅綠色盲男性（XᵃY）之致病等位基因必遺傳自母親（XᴬXᵃ），並將色盲基因傳給所有女兒。','表現型相同者基因型不一定相同（TT 與 Tt 皆為高莖）；生男生女機率在每次受孕均為獨立事件，各為 1/2，不受前面幾胎性別影響。','用棋盤方格法分析父親血型 A 型（異型合子 Iᴬi）與母親血型 B 型（異型合子 Iᴮi）生下四種血型子女的可能機率。',[
 ['若一對雙眼皮夫婦（皆為顯性異型合子 Bb），生下單眼皮孩子（bb）的理論機率為？',['100%','75%','50%','25%'],3,'Bb×Bb 配子組合為 BB(1/4)、Bb(2/4)、bb(1/4)，因此隱性性狀單眼皮機率為 1/4 (25%)。'],
 ['人類紅綠色盲為 X 染色體隱性遺傳。若父親視覺正常（XᴬY），母親為色盲（XᵃXᵃ），則其所生兒子的視覺狀況為？',['必定正常','必定色盲','一半機率色盲','無法由基因推算'],1,'兒子從父親繼承 Y 染色體，從母親必繼承一條帶有色盲基因的 Xᵃ 染色體（XᵃY），故必定為紅綠色盲。']]);
u('biology',7,2,'生物多樣性、保育與環境永續','生物多樣性包含遺傳多樣性（同物種個體間基因差異）、物種多樣性（區域內物種豐富與均勻度）與生態系多樣性（棲地與生態功能多樣）。維護生物多樣性是生態平衡與人類資源永續之基礎；棲地破碎、外來種入侵與過度開發是主要威脅。','臺灣櫻花鉤吻鮭為冰河孑遺生物，棲息於大甲溪上游七家灣溪高海拔冷水域，透過劃設野生動物保護區與水質改善維護其族群遺傳多樣性。福壽螺與小花蔓澤蘭等外來入侵種缺乏天敵，威脅本土生態。','物種多樣性高不只看物種種類多寡，還要看各物種個體數分布的均勻度；外來種不一定都會造成危害，只有大量繁殖並危害本土生態者才稱為「入侵種」。','調查校園或住家周遭常見的動植物，列出一種本土種與一種外來入侵種，分析外來種對環境可能帶來的衝擊與防治策略。',[
 ['評估一個森林生態系的「物種多樣性」時，需要同時考量哪兩項指標？',['物種種類數目與各物種個體分布均勻度','所有生物的總體重與樹木年齡','外來種所占的比例與森林面積大小','觀賞價值高低與木材經濟產值'],0,'物種多樣性取決於「物種豐富度」（種類數目）與「物種均勻度」（各種類族群數量的平衡性）。'],
 ['外來物種之所以容易在臺灣本土生態系中造成嚴重危害（成為入侵種），最主要的原因常是？',['體型必定比所有本土物種龐大','在新環境缺乏有效天敵且繁殖力強','能夠在短時間內自行改變染色體數目','只在寒冷高山地區活動'],1,'外來入侵種往往具有生長迅速、適應力與繁殖力強，且在引進地缺乏自然天敵與競爭者等優勢。']]);

u('physics',8,1,'浮力與阿基米德原理','浸在流體中的物體受到向上的浮力，浮力大小等於物體所排開的流體重量（B＝V_排×D_液）。物體密度小於液體密度時上浮為浮體（B＝物重）；密度大於液體密度時下沉為沈體（B＝V_物×D_液＜物重）。','體積 100 cm³、質量 80 g 的木塊投入水中，因木塊密度 0.8 g/cm³ 小於水，會浮在水面上，浮力等於物重 80 gw，排開水體積為 80 cm³。','浮體所受的浮力等於「物體本身重量」，不是排開全部物體體積的液體重；沈體沉入水底越深，若液體密度不變且未觸底壓緊，所受浮力維持不變。','拿一顆油土先捏成實心球放入水中觀察沉浮，再捏成碗狀小船放入水中，解釋為何相同質量的油土能浮起來。',[
 ['將質量 300 g、體積 500 cm³ 的保麗龍塊完全壓入純水中，此時保麗龍塊所受的浮力大小為？',['300 gw','500 gw','200 gw','800 gw'],1,'完全壓入水中時排開水體積等於物體體積 500 cm³，浮力＝500 cm³×1 g/cm³＝500 gw。'],
 ['同一顆鐵球先後放入純水（密度 1.0 g/cm³）與濃食鹽水（密度 1.2 g/cm³）中，鐵球皆沉入底部，則在何者中所受浮力較大？',['純水中較大','食鹽水中較大','兩者浮力相等','無法判斷'],1,'鐵球在兩液體中皆完全沒入（V_排相同），因食鹽水密度較大，依 B＝V_排×D_液，在食鹽水中浮力較大。']]);
u('physics',8,1,'液體壓力與大氣壓力','靜止液體中任意一點的液體壓力 P＝h×D（h為液面深度，D為液體密度），壓力方向垂直於接觸面且各方向相等。連通管各管液面等高；帕斯卡原理指出密閉液體傳遞壓力大小不變。托里切利實驗以水銀柱測定 1 大氣壓（1 atm＝76 cm-Hg＝1033.6 gw/cm²）。','液壓起重機小活塞面積 10 cm² 施力 50 kgw，可在面積 200 cm² 的大活塞上產生 50×(200/10)＝1000 kgw 的頂升力量。','液體壓力大小與容器形狀、粗細無關，只與「深度」及「液體密度」有關；托里切利管傾斜時，管內外水銀面的「垂直高度差」仍維持 76 cm 不變。','在寶特瓶上下垂直排列打三個小孔裝滿水，觀察三個水柱噴射距離的差異，說明液體壓力與深度的關係。',[
 ['在平靜的深水游泳池中，潛水員下潛越深，其身體所承受的液體壓力變化為？',['壓力越來越小','壓力維持不變','壓力越來越大','只在水平方向受壓'],2,'依液體壓力公式 P＝h×D，液面垂直深度 h 越深，液體所造成的靜水壓力越大。'],
 ['在標準一大氣壓下進行托里切利實驗，若將玻璃管由垂直稍微傾斜放置，則管內水銀柱的垂直高度差將？',['變長','變短','維持 76 公分不變','立刻降為零'],2,'大氣壓力支撐的水銀柱垂直重量不變，因此管內外水銀面的「垂直高度」仍維持 76 cm，但水銀柱長度會變長。']]);
u('physics',8,2,'摩擦力、正向力與牛頓第一運動定律深化','接觸面阻礙相對運動的力稱為摩擦力。靜止時所受摩擦力為靜摩擦力，大小隨外力增加而增加，最大值為最大靜摩擦力（與正向力及接觸面粗糙度有關）；運動時所受為動摩擦力，通常小於最大靜摩擦力。牛頓第一定律：合力為零時物體維持靜止或等速度直線運動。','推動 20 kgw 重箱子，最大靜摩擦力為 8 kgw。若水平施力 5 kgw，箱子不動，靜摩擦力即為 5 kgw；若施力 10 kgw 箱子移動，摩擦力轉為動摩擦力（如 6 kgw）。','物體未被推動時，靜摩擦力大小等於當時的「推力」，不等於最大靜摩擦力；滑動摩擦力與接觸面積大小通常無關。','將木塊置於不同表面（桌面、砂紙、墊板），用彈簧秤測量剛拉動木塊瞬間的讀數，比較最大靜摩擦力。',[
 ['重 50 N 的木塊靜置於粗糙水平桌面上，已知最大靜摩擦力為 20 N。若用 15 N 的水平力推木塊而木塊不動，此時木塊所受的摩擦力大小為？',['0 N','15 N','20 N','35 N'],1,'木塊維持靜止（合力為零），水平方向推力與靜摩擦力大小相等、方向相反，故摩擦力為 15 N。'],
 ['在無摩擦力的理想光滑冰面上，將一冰壺以 5 m/s 的初速推出，冰壺離開手後的運動狀態將是？',['速度越來越慢最後靜止','持續以 5 m/s 做等速度直線運動','速度越來越快','運動軌跡逐漸彎曲成圓形'],1,'依牛頓第一運動定律（慣性定律），若水平方向合力為零，運動中的物體將永遠維持原速度做等速度直線運動。']]);
u('physics',9,2,'靜電現象與庫侖定律','物質由帶正電質子與帶負電電子組成。摩擦使電子在不同物體間轉移，得電子者帶負電，失電子者帶正電。同性電荷相斥，異性電荷相吸。帶電體靠近不帶電導體會產生靜電感應。庫侖定律：兩電荷間的靜電力大小與電量乘積成正比，與距離平方成反比。','以毛皮摩擦塑膠尺，電子由毛皮轉移到塑膠尺使尺帶負電；帶電尺靠近細小紙屑時，紙屑近端產生感應異性電而被吸引。','摩擦起電並未創造新電荷，只是「負電荷（電子）」的轉移，原子核質子不會被摩擦脫離；帶電體能吸引不帶電輕小物體是由於「靜電感應」。','用氣球在頭髮上摩擦數次後靠近細小水流，觀察水流是否發生偏折，並解釋靜電吸引的成因。',[
 ['絲絹摩擦玻璃棒後，玻璃棒帶正電，關於摩擦過程中的微觀轉移敘述何者正確？',['質子從絲絹轉移到玻璃棒','電子從玻璃棒轉移到絲絹','玻璃棒創造出了額外的正電荷','絲絹失去了所有負電荷'],1,'固體摩擦起電是核外電子的移動。玻璃棒失去電子帶正電，絲絹得到電子帶等量負電。'],
 ['兩帶電體間之靜電力為 F。若兩電荷的電量皆維持不變，而將兩者間的距離拉大為原來的 3 倍，則彼此間的靜電力變為？',['3 F','9 F','1/3 F','1/9 F'],3,'依庫侖定律 F∝(q₁q₂)/r²，距離 r 變為 3 倍時，分母 r² 變為 9 倍，因此靜電力減為原來的 1/9。']]);
u('physics',9,2,'電流的磁效應與電磁鐵','奧斯特發現電流周圍存在磁場。長直導線電流磁場為同心圓，方向由安培右手定則判定（右手大拇指指向電流，四指彎曲指向磁場）；螺線管通電磁場類似條形磁鐵。在螺線管內放入軟鐵芯可大幅增強磁場，製成可由電流啟閉的電磁鐵。','螺線管中放入軟鐵棒，通電時磁力大增能吸起大量迴紋針，切斷電流磁性隨即消失；增加螺線管圈數或增大電流皆可提高磁力強度。','安培定則中使用「右手」而非左手；長直導線周圍磁場強度隨與導線距離增加而遞減，不是均勻磁場。','用漆包線在鐵釘上繞 50 圈連接乾電池與開關，測試能吸起的迴紋針數目，再改為 100 圈比較電磁鐵磁力。',[
 ['將一導線南北水平放置於磁針上方，當通以由南向北的電流時，磁針 N 極的偏轉方向由何項定則判斷？',['牛頓第三運動定律','安培右手定則','歐姆定律','阿基米德原理'],1,'電流產生磁場的方向使用安培右手定則判斷：大拇指指電流方向，四指環繞方向為磁場方向。'],
 ['想要增強一個螺線管電磁鐵的磁力強度，下列哪一種方法最有效可行？',['減少線圈的纏繞圈數','減小通過線圈的電流大小','在線圈中心插入軟鐵芯並增大電流','將線圈置於真空中'],2,'電磁鐵磁力大小與「線圈單位長度匝數」、「電流大小」及「是否具有高導磁軟鐵芯」成正相關。']]);
u('physics',9,2,'電磁感應與發電機','法拉第發現通過線圈的磁力線數目發生變化時，線圈會產生感應電流，稱為電磁感應。冷次定律指出感應電流產生的磁場總是反抗原磁場的變化。發電機利用力學能旋轉線圈切割磁力線產生交流電，是力學能轉電能；電動機（馬達）則是通電受磁力旋轉，是電能轉力學能。','將磁鐵 N 極快速插入線圈，線圈上端產生 N 極排斥其進入；將磁鐵靜止放在線圈內部時，磁場沒有變化，檢流計指針維持在 0 不偏轉。','只有在磁場「發生變化（運動或變動）」的瞬間才會產生感應電流；磁鐵靜止在線圈中無論磁性多強都不會產生感應電流。','搖晃手搖發電手電筒，觀察轉動速度越快時燈泡亮度如何變化，並說明能量形式的轉換過程。',[
 ['關於法拉第電磁感應現象，下列何種情況下線圈中「不會」產生感應電流？',['將磁鐵快速插入線圈過程中','將磁鐵快速從線圈抽出的過程中','磁鐵靜止放置於線圈內部不動時','線圈在均勻磁場中快速轉動時'],2,'電磁感應必須通過線圈的磁力線數目發生「時間上的變化」，磁鐵與線圈相對靜止時磁通量不變，不產生感應電流。'],
 ['水力發電廠利用水流帶動渦輪旋轉發電機產生電能，此過程主要的能量轉換形式為？',['力學能轉換為電能','電能轉換為熱能','化學能轉換為核能','光能轉換為力學能'],0,'發電機利用外力旋轉線圈切割磁力線產生感應電流，是將力學能（動能/位能）轉換為電能的裝置。']]);

u('chemistry',8,2,'反應速率與影響因素','化學反應速率衡量單位時間內反應物的消耗量或生成物的產生量。有效碰撞理論指出反應物粒子必須具有足夠能量與正確方向碰撞才能反應。影響速率的因素包括：反應物本性、接觸表面積（固體顆粒越小越快）、濃度（濃度越高碰撞機率越大）、溫度（升溫粒子動能增加且高能分子比例提升）與催化劑。','同質量的碳酸鈣，大理石粉末與鹽酸反應產生二氧化碳的速率遠快於整塊大理石塊；夏天食物容易腐壞是因為氣溫較高使化學與微生物分解反應速率加快。','催化劑（如二氧化錳催化雙氧水分解）能改變反應途徑降低活化能以加速反應，但反應前後其質量與化學性質不變，且不改變生成物的最大產量。','用等量發泡錠分別投入冰水、常溫水與溫水中，計時完全反應所需時間，繪製水溫與反應時間之關係圖。',[
 ['烤肉時將木炭敲碎成小塊更容易引燃且燃燒更劇烈，這主要是改變了哪一項影響反應速率的變因？',['反應物的化學本性','固體反應物的總接觸表面積','催化劑的加入','空氣中氧氣的百分濃度'],1,'固體顆粒敲碎後總表面積大幅增加，使木炭與空氣中氧氣分子的有效碰撞機率顯著提高。'],
 ['在雙氧水（H₂O₂）分解產生氧氣的實驗中加入二氧化錳（MnO₂），反應結束後二氧化錳的狀態應為？',['質量減少一半並變為新物質','質量與化學性質皆維持不變','完全消耗殆盡轉化為氧氣','質量因吸收氧氣而倍增'],1,'二氧化錳在該反應中擔任催化劑，可加快反應速率，但自身質量與化學性質在反應前後均不改變。']]);
u('chemistry',8,2,'化學平衡與勒沙特列原理','在密閉系統中，當正反應速率等於逆反應速率時，各物質的濃度不再改變，達到動態的化學平衡。勒沙特列原理指出當平衡系統受到外在條件（如濃度、溫度、壓力）干擾時，系統會朝著減弱該干擾方向移動以建立新平衡。','鉻酸鉀黃色水溶液（CrO₄²⁻）加酸（H⁺）時，平衡向右移動轉為紅橙色的二鉻酸根（Cr₂O₇²⁻）；若改加入氫氧化鈉鹼液中和 H⁺，平衡向左移動恢復為黃色。','化學平衡是「動態」平衡，正逆反應依然在進行，只是速率相等；平衡時各反應物與生成物的濃度保持固定，但兩者濃度不一定相等。','觀察密閉注射筒內的紅棕色二氧化氮（NO₂）與無色四氧化二氮（N₂O₄）氣體，快速壓縮注射筒觀察顏色先變深再變淺之平衡移動。',[
 ['當一個可逆化學反應在密閉容器中達到「化學平衡」時，下列敘述何者必然正確？',['反應完全停止，不再有任何分子碰撞','反應物與生成物的濃度必然完全相等','正反應速率等於逆反應速率','反應物已經完全耗盡轉化為產物'],2,'化學平衡為動態平衡，其核心條件是正反應速率與逆反應速率相等，宏觀濃度保持恆定。'],
 ['在黃色的鉻酸根離子（CrO₄²⁻）與紅橙色的二鉻酸根離子（Cr₂O₇²⁻）平衡溶液中滴加濃鹽酸（提供 H⁺），溶液顏色將如何變化？',['由黃色逐漸變為紅橙色','由紅橙色轉為完全透明無色','完全不變色','直接沉澱為黑色固體'],0,'2CrO₄²⁻＋2H⁺⇌Cr₂O₇²⁻＋H₂O，加入 H⁺ 增加反應物濃度，促使平衡向右移動生成更多紅橙色的 Cr₂O₇²⁻。']]);
u('chemistry',8,2,'電解質與阿瑞尼斯解離說','溶於水能導電的化合物稱為電解質，包括酸（如 HCl、HNO₃）、鹼（如 NaOH、KOH）與鹽類（如 NaCl、KNO₃）。阿瑞尼斯解離說提出電解質溶於水時會解離成帶正電的陽離子與帶負電的陰離子；水溶液中正負電荷總電量必然相等，全溶液維持電中性。','NaCl(s) 溶於水解離為 Na⁺ 與 Cl⁻，通電時陽離子向負極移動、陰離子向正極移動形成電流。蔗糖或乙醇（酒精）溶於水以分子狀態存在不解離，為非電解質。','金屬（如銅線）能導電但不是電解質（電解質必須是化合物且在水溶液中或熔融態導電）；電解質水溶液中陽離子數與陰離子數不一定相等（如 CaCl₂ 陽陰離子比為 1:2），但正負「總電量」必然相等。','使用簡單電路裝置（電池、LED燈泡與電極），檢驗糖水、純水、食鹽水與醋酸溶液的導電度並記錄燈泡亮度。',[
 ['下列物質溶於純水後，何者能解離出自由移動的離子而使水溶液導電（屬於電解質）？',['葡萄糖（C₆H₁₂O₆）','氯化氫氣體（HCl）','乙醇酒精（C₂H₅OH）','銅金屬片（Cu）'],1,'氯化氫溶於水形成鹽酸，會完全解離成氫離子（H⁺）與氯離子（Cl⁻），屬於強電解質。'],
 ['氯化鈣（CaCl₂）水溶液中含有大量的 Ca²⁺ 與 Cl⁻。關於該溶液中正負離子的敘述何者正確？',['Ca²⁺ 的總數目等於 Cl⁻ 的總數目','Ca²⁺ 所帶的正電總電量等於 Cl⁻ 所帶的負電總電量','溶液整體帶正電','通電時 Ca²⁺ 向電池正極移動'],1,'CaCl₂ 解離出 Ca²⁺:Cl⁻ 個數比為 1:2，但每個 Ca²⁺ 帶 +2 電荷、每個 Cl⁻ 帶 -1 電荷，正負總電量相等，溶液維持電中性。']]);
u('chemistry',8,2,'酸鹼滴定與常見生活鹽類','酸鹼中和反應本質為 H⁺＋OH⁻→H₂O，必為放熱反應。酸鹼滴定利用已知濃度之酸（或鹼）測定未知濃度之鹼（或酸），當莫耳數相等時達到當量點，以酚酞（酸性無色、鹼性紅）或石蕊等指示劑判斷滴定終點。生活常見鹽類：氯化鈉（調味保鮮）、碳酸鈣（大理石石灰石主要成分）、碳酸氫鈉（小蘇打，烘焙加熱產生 CO₂）。','胃酸過多時服用含碳酸氫鈉（小蘇打）或氫氧化鋁的胃藥中和胃酸；烘焙蛋糕時小蘇打受熱分解：2NaHCO₃→Na₂CO₃＋H₂O＋CO₂，產生的二氧化碳氣體使蛋糕蓬鬆。','酸鹼中和必放熱，溶液溫度會上升；中和生成的鹽類水溶液不一定為中性（如碳酸氫鈉水溶液呈弱鹼性，氯化銨呈弱酸性）。','以紅鳳菜或紫色高麗菜汁自製天然酸鹼指示劑，測試醋、檸檬水、肥皂水與小蘇打水的呈色變化。',[
 ['將 0.1 M 的鹽酸溶液慢慢滴入裝有氫氧化鈉溶液與酚酞指示劑的錐形瓶中，滴定過程中溶液顏色的變化為？',['由紅色逐漸褪色變為無色','由無色逐漸變為深紅色','由藍色轉變為鮮黃色','全程完全不變色'],0,'氫氧化鈉呈鹼性使酚酞呈紅色，隨鹽酸滴入中和 OH⁻，當達到滴定終點時溶液呈中性或弱酸性，酚酞變為無色。'],
 ['做麵包或餅乾時常加入的「小蘇打粉」，受熱後能產生氣體使食品蓬鬆，其主要化學成分是？',['碳酸鈣（CaCO₃）','碳酸氫鈉（NaHCO₃）','硫酸銅（CuSO₄）','氫氧化鈉（NaOH）'],1,'小蘇打為碳酸氫鈉（NaHCO₃），受熱易分解產生二氧化碳（CO₂）氣體、水與碳酸鈉。']]);
u('chemistry',9,2,'常見有機化合物與石化燃料','含碳化合物多為有機化合物（CO、CO₂、碳酸鹽與氰化物等除外）。烴類僅由碳氫組成：烷類單鍵、甲烷（CH₄）為天然氣主要成分、丙烷（C₃H₈）與丁烷為液化石油氣成分。醇類含羥基（—OH），乙醇（酒精）可溶於水作溶劑與消毒劑；有機酸含羧基（—COOH），乙酸（醋酸）具酸性。醇與酸在濃硫酸催化下發生酯化反應生成具香味的酯類與水。','乙酸與乙醇加入少許濃硫酸加熱：CH₃COOH＋C₂H₅OH→CH₃COOC₂H₅＋H₂O，生成的乙酸乙酯難溶於水且密度小於水，浮在表面散發芳香果香。','濃硫酸在酯化反應中擔任「催化劑」與「脫水劑」，非反應物；含碳的化合物不全是有機物，一氧化碳、二氧化碳與大理石（CaCO₃）歸為無機化合物。','比較家用瓦斯桶（液化石油氣，主成分丙烷丁烷）與管線瓦斯（天然氣，主成分甲烷）的組成與安全注意事項。',[
 ['下列物質中，屬於化學分類上的「有機化合物」的是？',['一氧化碳（CO）','碳酸鈣（CaCO₃）','乙酸醋酸（CH₃COOH）','氰化鉀（KCN）'],2,'乙酸為有機酸；CO、CO₂、碳酸鹽（如 CaCO₃）及氰化物習慣上被歸類為無機化合物。'],
 ['乙醇與乙酸在濃硫酸催化並加熱的條件下進行化學反應，主要生成的有機產物是？',['甲烷氣體','乙酸乙酯','葡萄糖','碳酸鈉'],1,'有機酸（乙酸）與醇類（乙醇）進行酯化反應，脫水生成具有芳香氣味的酯類（乙酸乙酯）與水。']]);
u('chemistry',9,2,'聚合物與生活材料安全','聚合物由數千個以上單體重複鍵結形成的高分子化合物。天然聚合物包括澱粉、纖維素、蛋白質與天然橡膠；合成聚合物包括合成纖維、合成橡膠與塑膠。熱塑性塑膠具鏈狀結構，受熱易軟化可回收再製（如保特瓶 PET、聚乙烯 PE）；熱固性塑膠具網狀交聯結構，受熱不熔化具耐熱性（如美耐皿、環氧樹脂）。','聚乙烯（PE）由乙烯（C₂H₄）單體加聚而成，為鏈狀結構熱塑性塑膠；寶特瓶回收標誌 1 號為聚乙烯對苯二甲酸酯（PET），加熱可重新拉絲製成環保衣物。','澱粉與纖維素的單體皆為葡萄糖，但因幾何連接方式不同，人體酵素能消化澱粉卻無法分解纖維素；塑膠燃燒可能產生戴奧辛等有毒氣體，需落實源頭減量與分類回收。','檢視家中三個塑膠容器底部的三角回收標誌編號（1 至 7 號），查閱各自耐熱溫度與材質特性，列出正確使用指引。',[
 ['下列生活材料中，何者屬於「天然聚合物」？',['聚乙烯塑膠袋（PE）','雞蛋中的蛋白質','耐綸尼龍繩索（Nylon）','特氟龍不沾鍋塗層（PTFE）'],1,'蛋白質是由多種胺基酸單體縮合而成的天然高分子聚合物；其餘皆為人工石化合成聚合物。'],
 ['保特瓶與塑膠水杯受熱容易變形軟化、冷卻後變硬，能重複加熱塑形回收，這類塑膠的分子結構屬於？',['網狀結構的熱固性聚合物','單一無鍵結的小分子氣體','鏈狀結構的熱塑性聚合物','完全不含碳的無機晶體'],2,'鏈狀結構的熱塑性塑膠分子鏈間無化學交聯鍵，加熱時分子鏈容易滑動而軟化熔融，適合回收重製。']]);

u('earth',9,1,'地層順序與地質歷史判讀','地質學家透過地層與化石推斷地球歷史。疊置定律指出未受擾動沉積岩下老上新；截切定律指出截切岩層的斷層或岩脈必定比被截切的岩層年輕；包裹定律指出岩石中所含的包裹塊必定比母岩古老。標準化石（分布廣、生存時期短、特徵明顯）可用於劃定地質年代（如三葉蟲為古生代、菊石恐龍為中生代）。','若一岩層沉積後被一條岩脈貫穿，且岩脈又被一條斷層切斷，則形成順序依序為：岩層沉積最老，岩脈入侵次之，斷層錯動最年輕。','地層若經歷強烈造山運動發生地層倒轉，則疊置定律必須配合沉積構造（如交錯層、波痕）校正；指相化石（如珊瑚代表溫暖清澈淺海）反映環境，與定年用的標準化石功能不同。','畫出一個包含沉積岩層 A、B、C 及侵入岩脈 D 和斷層 E 的地質剖面圖，排出各事件發生的先後順序並解釋依據。',[
 ['在地質剖面中，若一條垂直的火山岩脈截切穿透了水平的沉積砂岩層與頁岩層，依截切定律判斷兩者年齡順序為？',['岩脈年齡比砂岩頁岩更老','砂岩頁岩形成時間比岩脈更早','兩者必然在同一天同時形成','無法由剖面截切關係推斷'],1,'截切定律：截切者較年輕，被截切者較老。砂岩與頁岩必須先沉積存在，岩漿岩脈才能貫穿截切它們。'],
 ['若在一處沉積岩層中挖掘出大量的「三葉蟲化石」，則該地層沉積的地質年代最可能為？',['新生代', '中生代', '古生代', '前寒武紀'],2,'三葉蟲是古生代（海洋無脊椎動物盛行時期）極具代表性的標準化石，於古生代末期大滅絕中滅絕。']]);
u('earth',9,1,'板塊構造學說與臺灣造山運動','岩石圈（地殼與地函最上部）破裂成數個板塊，在軟流圈熱對流帶動下運動。板塊邊界分為張裂型（如中洋脊、東非大裂谷，形成新地殼）、聚合型（如海溝、摺皺山脈，板塊隱沒碰撞消滅）與錯動型（如聖安德烈斯斷層）。臺灣位處歐亞板塊與菲律賓海板塊聚合碰撞邊界，造山運動強烈、地震頻繁且地質破碎。','花東縱谷是歐亞大陸板塊與菲律賓海板塊（海岸山脈）的縫合帶；菲律賓海板塊在臺灣東北方向下隱沒至歐亞板塊之下，形成大屯火山群與基隆火山群。','板塊不等於大洲或地殼，板塊厚度包含地殼與固態上地函頂部（岩石圈）；花東縱谷兩側分別屬於不同板塊，西側中央山脈屬歐亞板塊，東側海岸山脈屬菲律賓海板塊。','在臺灣地圖上標示中央山脈、花東縱谷與海岸山脈，用箭頭畫出歐亞板塊與菲律賓海板塊的相對運動方向。',[
 ['大西洋中洋脊兩側的海底岩層持續向兩側擴張並湧出玄武岩漿，該處板塊邊界類型屬於？',['聚合型板塊邊界','張裂型板塊邊界','錯動型板塊邊界','穩定地塊邊界'],1,'中洋脊是地函熱對流上升處，板塊在此相互拉開分離，屬於張裂型板塊邊界，持續生成新海洋地殼。'],
 ['臺灣島之所以高山林立且地震非常頻繁，在地質板塊構造上的主要原因是？',['位處板塊中央的極度穩定地塊','歐亞大陸板塊與菲律賓海板塊在此強烈碰撞擠壓','非洲板塊與美洲板塊在此張裂拉開','太平洋中洋脊貫穿臺灣中央'],1,'臺灣位於歐亞板塊與菲律賓海板塊的聚合型交界帶，板塊持續碰撞擠壓產生強烈褶皺造山與斷層地震。']]);
u('earth',9,1,'大氣氣團、鋒面系統與天氣災害','源於廣大地區且溫度與濕度均勻的空氣塊稱為氣團。冷暖氣團交會的狹窄過渡帶稱為鋒面：冷鋒是冷空氣主動推擠暖空氣，暖空氣劇烈抬升常帶來雷雨或驟雨，過境後氣溫驟降氣壓上升；暖鋒暖空氣爬升冷空氣之上帶來連續性降水；滯留鋒勢均力敵停滯徘徊，是臺灣 5、6 月梅雨季節連日降雨的主因。','冬季西伯利亞大陸冷高壓南下帶來強烈東北季風，當冷鋒過境臺灣時，氣溫劇烈下降且迎風面北臺灣降雨明顯；夏秋之際西北太平洋生成的熱帶氣旋（颱風）帶來強風豪雨。','冷氣團密度較大貼近地面，暖氣團密度較小必被抬升到冷空氣上方；鋒面降雨雲系通常出現在鋒面後方（冷鋒）或前方（暖鋒）的冷空氣一側。','收集一張中央氣象署的地面天氣圖，辨識冷鋒、暖鋒與滯留鋒符號，並指出高氣壓（H）與低氣壓（L）中心位置。',[
 ['當一強烈冷鋒過境某城市時，該城市在短時間內最常觀測到的氣象特徵變化是？',['氣溫驟降、氣壓上升並伴隨陣雨或雷雨','氣溫急遽上升、天氣轉為萬里無雲乾燥','氣壓大幅下降、風速瞬間歸零','所有降雨完全停止且連續數天酷熱'],0,'冷鋒過境時冷空氣推擠暖空氣劇烈抬升形成厚厚積雨雲，帶來短暫降雨，過境後冷空氣籠罩使氣溫下降、氣壓回升。'],
 ['臺灣每年五、六月間常出現連日陰雨綿綿的「梅雨」天氣，這主要是受哪一種鋒面系統停滯影響所致？',['冷鋒','暖鋒','滯留鋒','囚錮鋒'],2,'梅雨期是由於北方冷氣團與南方暖濕季風勢均力敵，在臺灣附近形成滯留鋒徘徊不前，造成持續性降雨。']]);
u('earth',9,2,'天體引力、潮汐現象與月相變化','潮汐主要是月球與太陽對地球海水的引潮力（萬有引力差）引起的週期性升降。海水面升到最高為滿潮，降到最低為乾潮，滿潮與乾潮之水位差為潮差。新月（農曆初一）與滿月（農曆十五）時太陽、地球、月球三者大致成一直線，引潮力相加形成「大潮」；上弦月與下弦月時日地月成垂直直角，引潮力部分抵消形成「小潮」。','臺灣西部沿海（如臺中、彰化）因海峽地形效應潮差可達 4 公尺以上，造就廣大的泥質潮間帶生態；一天通常有兩次滿潮與兩次乾潮，相鄰兩次滿潮間隔約 12 小時 25 分。','潮汐週期不是剛好 12 小時，因為月球繞地球公轉，每天滿潮時間會延遲約 50 分鐘；大潮是潮差最大（滿潮最高、乾潮最低），非單純海水永遠最多。','查詢離你最近的海邊潮汐預報表，找出未來三天的滿潮與乾潮時間，計算潮差大小並推算當天月相。',[
 ['農曆每月的初一（新月）與十五（滿月）前後，當地的潮汐現象通常會出現？',['整天完全沒有潮差','潮差最大的「大潮」','潮差最小的「小潮」','海水只退不漲'],1,'新月與滿月時太陽、月球與地球大致排成一直線，太陽引潮力與月球引潮力疊加，使滿潮更高、乾潮更低，形成「大潮」。'],
 ['已知某海港今天第一次滿潮時間為清晨 06:00，則同日下一次滿潮發生的時間大約會落在？',['中午 12:00 整','下午 18:25 左右','晚上 24:00 整','翌日清晨 06:00'],1,'由於月球公轉，半日潮週期約為 12 小時 25 分鐘，因此第二次滿潮約於 18:25 左右發生。']]);
}

